import{z as s,x as B,o as e,c as d,q as A,j as n,D as E,d as l,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"编码器-解码器对纯解码器","description":"","frontmatter":{"title":"编码器-解码器对纯解码器","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/encdec-vs-decoder-only.md","filePath":"llm/encdec-vs-decoder-only.md","lastUpdated":1791413859000}'),i={name:"llm/encdec-vs-decoder-only.md"};function p(m,a,c,h,D,_){const t=B("Mermaid");return e(),d("div",null,[a[2]||(a[2]=A('<h1 id="编码器-解码器对纯解码器" tabindex="-1">编码器-解码器对纯解码器 <a class="header-anchor" href="#编码器-解码器对纯解码器" aria-label="Permalink to &quot;编码器-解码器对纯解码器&quot;">​</a></h1><div class="epigraph"><p>若把所有任务都写成文本进、文本出，编码器–解码器与纯解码器都能做；差别在源是否值得单独做一次双向编码。</p><footer>—— 综合 Raffel et al., T5, JMLR 2020；Radford et al., Language Models are Unsupervised Multitask Learners, 2019</footer></div><p><a href="/llm/bart-denoising">上一课</a>给出去噪编解码：源完整且常被损坏，目标自回归写出。主干从 GPT 一路下来却把条件也塞进同一条因果前缀。本课不发明第三种注意力，只把两种计算图并排，问什么时候值得付编码器的双向平方代价与交叉注意力槽位。后课的前缀掩码是折中，嵌入池化则站在编码器一侧；本课先把分界画清。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/encoder-decoder-attention">编码器–解码器注意力</a>假定源 \\(y_{1:m}\\) 一次给齐、适合双向；<a href="/llm/causal-self-attention">因果自注意力</a>假定只有一条从左到右的序列。条件生成可以把源当前缀拼在目标左边，用块状掩码让前缀内部双向、目标仍因果——但那是下一课。本课的缺口更粗：在还没有前缀掩码的工具箱里，<strong>两套独立栈</strong>对 <strong>一套因果栈</strong>，算力、表示、微调接口各付出什么。</p><p>T5 把翻译、摘要、问答都收成编解码；GPT-2 把同样的任务收成提示续写。后课不能一会儿假设有交叉注意力、一会儿假设没有。</p><p><span class="marginnote">「纯解码器也能做翻译」不是本课要反驳的命题。本课要写清：能做不等于源侧表示相同。前缀里的源 token 从未以双向方式互相看见，除非掩码特意打开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编解码器：编码器 \\(L\\) 层双向，复杂度 \\(\\Theta(L m^2 d)\\)；解码器 \\(L\\) 层因果自注意力 \\(\\Theta(L n^2 d)\\) 加交叉注意力 \\(\\Theta(L n m d)\\)。源在训练与推理都完整可见。纯解码器：单栈 \\(L\\) 层，序列长度 \\(m+n\\)，因果掩码，复杂度 \\(\\Theta(L(m+n)^2 d)\\)。推理时源前缀的 KV 可以缓存，之后每步只增长目标。</p><p>参数上，编解码器常有两套（或共享的）层权重，交叉注意力还多一组 \\(W^Q,W^K,W^V\\)。纯解码器参数更整齐，和训练基础课里的合并、任务向量更同构——这也是为何补层第一课之前默认解码器只。</p><h3 id="何时源值得双向" tabindex="-1">何时源值得双向 <a class="header-anchor" href="#何时源值得双向" aria-label="Permalink to &quot;何时源值得双向&quot;">​</a></h3><p>源内部的约束是双向的（句子是否通顺、指代在后面才消解、文档级一致性），且源在推理时确实齐，双向编码器一次写记忆，交叉注意力反复读，比让源 token 只能看见自己的左边更省「源内交互」。源极短或源就是「请继续写」这类提示，双向的边际收益小，纯解码器少一套模块。</p><p><span class="marginnote">数字实例：取 \\(m=512\\)、\\(n=64\\)。编解码器每层注意力约 \\(512^2+512\\times64+64^2\\approx30\\) 万个位置对；纯解码器 \\((512+64)^2\\approx33\\) 万。源远长于目标时，编解码器反而便宜约一成，还没算源内双向带来的表示差别。</span></p>',13)),(e(),n(o,null,{default:E(()=>[r(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%9D%A1%E4%BB%B6%E7%94%9F%E6%88%90%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20S%7B%22%E6%BA%90%E5%9C%A8%E6%8E%A8%E7%90%86%E6%97%B6%E4%B8%80%E6%AC%A1%E7%BB%99%E9%BD%90%3F%22%7D%0A%20%20S%20--%20%22%E5%90%A6%2C%20%E8%BE%B9%E5%A4%84%E7%90%86%E8%BE%B9%E5%87%BA%E6%BA%90%22%20--%3E%20DEC%5B%22%E7%BA%AF%E8%A7%A3%E7%A0%81%E5%99%A8%3A%20%E6%BA%90%E5%BD%93%E5%89%8D%E7%BC%80%22%5D%0A%20%20S%20--%20%22%E6%98%AF%22%20--%3E%20L%7B%22%E6%BA%90%E9%95%BF%E4%B8%94%E5%86%85%E9%83%A8%E7%BA%A6%E6%9D%9F%E5%BC%BA%3F%22%7D%0A%20%20L%20--%20%22%E6%98%AF%22%20--%3E%20ED%5B%22%E7%BC%96%E8%A7%A3%E7%A0%81%E5%99%A8%3A%20%E5%8F%8C%E5%90%91%E7%BC%96%E7%A0%81%20%2B%20%E4%BA%A4%E5%8F%89%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20L%20--%20%22%E5%90%A6%2C%20%E6%BA%90%E6%9E%81%E7%9F%AD%E6%88%96%E5%8F%AA%E6%98%AF%E6%8F%90%E7%A4%BA%22%20--%3E%20DEC2%5B%22%E7%BA%AF%E8%A7%A3%E7%A0%81%E5%99%A8%3A%20%E5%B0%91%E4%B8%80%E5%A5%97%E6%A8%A1%E5%9D%97%22%5D%0A%20%20DEC%20--%3E%20DECN%5B%22%E6%BA%90%20token%20%E5%8F%AA%E8%A7%81%E5%B7%A6%E4%BE%A7%2C%20%E6%97%A0%E6%BA%90%E5%86%85%E5%8F%8C%E5%90%91%22%5D%0A%20%20ED%20--%3E%20EDN%5B%22%E4%BA%A4%E5%8F%89%E9%A1%B9%20L%20n%20m%20%E5%B8%B8%E5%B0%8F%E4%BA%8E%20L%20(m%2Bn)%5E2%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>编解码器把对齐从自注意力里拆出来：目标前缀混合与源检索不是同一张分数矩阵。纯解码器把两者挤在同一张下三角里，源与目标的相对位置、分隔符、提示模板必须承担分界。长源短目标时，编解码器的 \\(nm\\) 交叉项往往小于 \\((m+n)^2\\) 的自注意力；长目标短源时，纯解码器更简单。</p><p><span class="marginnote">术语翻译：交叉注意力就是解码器每写一个词，回头「翻阅」编码器笔记的动作——Q 来自当前词，K、V 来自源记忆。它与「只在自己写过的内容里往前翻」的因果自注意力是两种查阅，所以也各自占一组参数。</span></p><p>微调接口：编解码器天然是「改源、改目标」；纯解码器是「改提示、改续写」。BART 去噪、T5 的 text-to-text 站在前者；指令微调、思维链站在后者。任务向量算术在两套栈之间不能直接加减。</p><p><span class="marginnote">共享编码器与解码器权重（有的 T5 变体）能减小参数，但不能把交叉注意力消掉。消掉交叉注意力，就不再是本课所说的编解码器。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课比较的是标准全注意力实现，不计稀疏、线性核、MoE。前缀掩码会把纯解码器的源段改成双向，分界会移动——那是下一课的补差，不是本课已经把纯解码器升级成编码器。检索、嵌入模型需要句向量，编解码器的编码器端现成，纯解码器往往要另做池化或双向微调。</p><p><span class="marginnote">常见误区：初学者容易以为「纯解码器加了前缀掩码就等于编码器–解码器」。前缀双向确实补上了源内交互，但交叉注意力那张独立的分数矩阵仍然没有——分界移动了，架构账并没有归零。</span></p>',8)),(e(),n(o,null,{default:E(()=>[r(t,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20EncDec%5B%22%E7%BC%96%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A%20%20%20%20E%5B%22%E5%8F%8C%E5%90%91%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%20--%3E%20M%5B%22%E6%BA%90%E8%AE%B0%E5%BF%86%22%5D%0A%20%20%20%20M%20--%3E%20C%5B%22%E4%BA%A4%E5%8F%89%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20%20%20D%5B%22%E5%9B%A0%E6%9E%9C%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%20--%3E%20C%0A%20%20end%0A%20%20subgraph%20Dec%5B%22%E7%BA%AF%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A%20%20%20%20P%5B%22%E6%BA%90%E5%89%8D%E7%BC%80%E5%8A%A0%E7%9B%AE%E6%A0%87%22%5D%20--%3E%20A%5B%22%E5%9B%A0%E6%9E%9C%E8%87%AA%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20end%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>编解码器为「源齐、目标自回归」付双向编码加交叉注意力；纯解码器把条件写进同一条因果前缀。</li><li>长源短目标时 \\(nm\\) 交叉常比 \\((m+n)^2\\) 便宜，且源内双向是真交互。</li><li>参数与检查点形状不同，任务向量不能跨架构加减。</li><li>前缀掩码尚未引入；不要把本课的纯解码器当成已经能双向读源。</li><li>出处：Raffel et al., <em>T5</em>, JMLR 2020；Radford et al., <em>GPT-2</em>, 2019。</li></ul>',2))])}const u=s(i,[["render",p]]);export{f as __pageData,u as default};
